package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	const N = 200000
	comp := make([]bool, N+1)
	cnt := make([]int, N+1)
	last := make([]int, N+1)
	for i := 2; i <= N; i++ {
		if !comp[i] {
			for j := i * i; j <= N; j += i {
				comp[j] = true
			}
		}
	}
	for i := 0; i <= N; i++ {
		if i > 0 {
			cnt[i] = cnt[i-1]
			last[i] = last[i-1]
		}
		if i >= 2 && !comp[i] {
			cnt[i]++
			last[i] = i
		}
	}
	r := bufio.NewReader(os.Stdin)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	var t int
	fmt.Fscan(r, &t)
	for ; t > 0; t-- {
		var n int
		if _, err := fmt.Fscan(r, &n); err != nil {
			break
		}
		if n < 2 {
			fmt.Fprintln(w, "0 none")
		} else {
			fmt.Fprintln(w, cnt[n], last[n])
		}
	}
}
